#!/usr/bin/env python3
# WARNING: This file is autogenerated - changes will be overwritten when regenerated by https://github.com/pulumi/ci-mgmt
"""Mirror the repo's mise toolchain into a global drop-in, so it resolves anywhere.

mise shims resolve a version from the *caller's* working directory. Anything that
runs outside the repo therefore sees no toolchain at all - tfgen converts examples
from a temp dir, and the build dies there. This writes what the repo pins into a
mise global config, which is the layer that applies when no repo config does.
Inside the repo nothing changes: the repo config still wins.

Three tables get mirrored, and the first two are read from the repo's own mise
config files rather than from mise's merged view:

    tools     resolved versions, so an out-of-tree caller gets what the repo pins
    env       only vars the repo declares - PULUMI_HOME above all, since it points
              plugin lookup at the repo and an out-of-tree `pulumi` finds no
              converters without it
    plugins   URLs for custom backends, which stop resolving if they are missing

Reading the config files is what keeps this honest. mise's merged view already
includes this drop-in, so sourcing keys from it would re-adopt whatever a previous
run wrote and never let go. The rendered file is parsed before it is written, too:
it lands in a global config directory, so a malformed one breaks every mise shim in
the sandbox rather than just this repo's.

Imported by the setup and start hooks; not a hook itself.
"""

from __future__ import annotations

import json
import os
import subprocess
from pathlib import Path


# Exported by setup.py / start.py, which resolve it once.
REPO_ROOT = Path(os.environ["REPO_ROOT"]).resolve()

# Named for the repo so the drop-in is identifiable among any others in conf.d.
DROP_IN_NAME = f"00-openinspect-{REPO_ROOT.name}.toml"

MISE_CONFIG_DIR = Path(
    os.environ.get("MISE_CONFIG_DIR")
    or Path(os.environ.get("XDG_CONFIG_HOME") or Path.home() / ".config") / "mise"
)


def mise_json(*args: str):
    """Run a mise command in the repo and parse its JSON output.

    Offline: only the declared versions matter here, and `mise env` would
    otherwise install anything missing - a fresh download mid-hook on any branch
    that bumps a pin. An uninstalled version in the drop-in is fine; the shim
    installs it on first use.
    """
    try:
        proc = subprocess.run(
            ["mise", *args],
            cwd=REPO_ROOT,
            check=True,
            capture_output=True,
            text=True,
            encoding="utf-8",
            timeout=30,
            env={**os.environ, "MISE_OFFLINE": "1"},
        )
    except subprocess.CalledProcessError as exc:
        # capture_output swallows mise's diagnostic; without this the caller
        # sees only a non-zero exit code.
        raise RuntimeError(f"mise {' '.join(args)} failed:\n{exc.stderr}") from exc
    return json.loads(proc.stdout)


def repo_configs() -> list:
    """Every mise config the repo itself owns, parsed."""
    try:
        import tomllib
    except ImportError:
        # Pre-3.11 interpreter: tools still resolve, but [env] and [plugins]
        # are skipped rather than taking on a dependency.
        print("no tomllib; skipping [env] and [plugins] - tools only")
        return []

    configs = []
    for config in mise_json("config", "ls", "--json"):
        path = Path(config.get("path", "")).resolve()
        if REPO_ROOT not in path.parents:
            continue
        try:
            with path.open("rb") as handle:
                configs.append(tomllib.load(handle))
        except (OSError, ValueError) as exc:
            print(f"skipping unreadable mise config {path}: {exc}")
    return configs


def repo_tools() -> dict[str, str]:
    """Resolved version of every tool the repo's own config declares.

    Keyed by the backend-qualified name mise reports (`github:pulumi/pulumi`,
    `go`, `npm:yarn`, ...). The *resolved* version is what gets written, never
    the requested one - some pins are templates (`{{ env.GO_VERSION_MISE }}`)
    that only evaluate against the repo config.
    """
    tools: dict[str, str] = {}
    unresolved: list[str] = []
    for name, entries in mise_json("ls", "--current", "--json").items():
        owned = [
            entry
            for entry in entries
            if (source := (entry.get("source") or {}).get("path"))
            and REPO_ROOT in Path(source).resolve().parents
        ]
        if not owned:
            continue
        # A list pin produces several entries ordered by version rather than by
        # declaration, so the first is not the one mise would use. mise flags the
        # primary as active; falling back to the first only matters before
        # anything is installed, when nothing is active yet.
        entry = next((e for e in owned if e.get("active")), owned[0])
        version = entry.get("version")
        if version:
            tools[name] = version
        else:
            unresolved.append(name)
    if unresolved:
        # A partial drop-in still writes and still reports a count, so name what
        # is missing rather than letting it surface later as a missing shim.
        print(f"no resolved version, omitting: {', '.join(sorted(unresolved))}")
    return tools


def repo_env(configs: list) -> dict[str, str]:
    """Resolved values for the env vars the repo's own configs declare.

    Keys from the configs, values from mise: the config gives provenance, mise
    resolves templates like `{{config_root}}`. Keys taken from mise alone would
    also pull in tool-contributed vars the repo never asked for.
    """
    declared = set()
    for config in configs:
        env = config.get("env") or {}
        # mise accepts `[env]` and `[[env]]` alike; the array form parses as a
        # list of tables, so normalize before reaching for keys.
        for table in env if isinstance(env, list) else [env]:
            declared.update(
                key
                for key in table
                # `_.file`, `_.path`, `_.source` and friends are directives.
                if not key.startswith("_")
            )
    return {
        key: value
        for key, value in mise_json("env", "--json").items()
        if key in declared and isinstance(value, str)
    }


def repo_plugins(configs: list) -> dict[str, str]:
    """Plugin URLs declared by the repo, so custom backends stay resolvable."""
    plugins: dict[str, str] = {}
    for config in configs:
        for name, url in (config.get("plugins") or {}).items():
            if isinstance(url, str):
                plugins[name] = url
    return plugins


def toml_string(value: str) -> str:
    """Quote a string so TOML accepts it.

    JSON escaping is nearly TOML's, with a gap either way: `json` leaves U+007F
    raw, and its `\\uXXXX` form spells non-BMP characters as surrogate pairs.
    TOML rejects both - hence `ensure_ascii=False` plus the one substitution.
    """
    return json.dumps(value, ensure_ascii=False).replace("\x7f", "\\u007F")


def toml_table(title: str, entries: dict[str, str]) -> list[str]:
    if not entries:
        return []
    lines = [f"[{title}]"]
    lines += [f"{toml_string(k)} = {toml_string(v)}" for k, v in sorted(entries.items())]
    return lines + [""]


def main() -> None:
    tools = repo_tools()
    if not tools:
        print("no repo-declared mise tools resolved; leaving the global config alone")
        return

    configs = repo_configs()
    body = [
        "# Generated on sandbox boot by .openinspect/mise_global_fallback.py.",
        "# Lets the repo's toolchain resolve from working directories outside the",
        "# repo, where no repo mise config applies. Edits here are overwritten.",
        "",
        "[settings]",
        # The generated config pins tools through backends (github:, go:, vfox:)
        # that mise only resolves with this on.
        "experimental = true",
        "",
    ]
    body += toml_table("plugins", repo_plugins(configs))
    body += toml_table("env", repo_env(configs))
    body += toml_table("tools", tools)
    rendered = "\n".join(body).rstrip() + "\n"

    try:
        import tomllib

        tomllib.loads(rendered)
        # tomllib works on str and accepts a lone surrogate that UTF-8 cannot
        # encode, so the write below would raise instead of this.
        rendered.encode("utf-8")
    except ImportError:
        pass
    except (ValueError, UnicodeEncodeError) as exc:
        raise RuntimeError(f"refusing to write unparseable mise config: {exc}") from exc

    # Every name written here resolves for every process in the sandbox, so
    # anything needing the environment's own copy of a tool the repo pins has to
    # invoke it by absolute path.
    drop_in = MISE_CONFIG_DIR / "conf.d" / DROP_IN_NAME
    drop_in.parent.mkdir(parents=True, exist_ok=True)
    # Staged and moved so a reader never catches the truncated file a plain
    # write leaves behind; UTF-8 explicitly, since the default follows the
    # locale and this emits non-ASCII verbatim.
    staged = drop_in.with_suffix(".toml.tmp")
    staged.write_text(rendered, encoding="utf-8")
    os.replace(staged, drop_in)

    print(f"wrote {drop_in} with {len(tools)} tools")


if __name__ == "__main__":
    main()
